package com.financetrack.repository;
import com.financetrack.entity.Expense; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Query; import org.springframework.data.repository.query.Param; import java.time.LocalDate; import java.util.*; import java.math.BigDecimal;
public interface ExpenseRepository extends JpaRepository<Expense,Long>{List<Expense> findByUserIdAndOccurredOnBetweenOrderByOccurredOnDesc(Long userId,LocalDate from,LocalDate to); Optional<Expense> findByIdAndUserId(Long id,Long userId); @Query("select coalesce(sum(e.amount),0) from Expense e where e.user.id=:uid and e.occurredOn between :from and :to") BigDecimal total(@Param("uid")Long uid,@Param("from")LocalDate from,@Param("to")LocalDate to); @Query("select e.category.name, sum(e.amount) from Expense e where e.user.id=:uid and e.occurredOn between :from and :to group by e.category.name") List<Object[]> byCategory(@Param("uid")Long uid,@Param("from")LocalDate from,@Param("to")LocalDate to);}
